28	/**
29	 * Matrix multiplication: C = A * B.
30	 * Host code.
31	 *
32	 * This sample implements matrix multiplication which makes use of shared memory
33	 * to ensure data reuse, the matrix multiplication is done using tiling approach.
34	 * It has been written for clarity of exposition to illustrate various CUDA programming
35	 * principles, not with the goal of providing the most performant generic kernel for matrix multiplication.
36	 * See also:
37	 * V. Volkov and J. Demmel, "Benchmarking GPUs to tune dense linear algebra,"
38	 * in Proc. 2008 ACM/IEEE Conf. on Supercomputing (SC '08),
39	 * Piscataway, NJ: IEEE Press, 2008, pp. Art. 31:1-11.
40	 */
41	
42	// System includes
43	#include <assert.h>
44	#include <stdio.h>
45	
46	// CUDA runtime
47	#include <cuda_runtime.h>
48	// The CUDA Safe runtime does not ship the profiler API; gate it on header availability.
49	#if defined(__has_include) && __has_include(<cuda_profiler_api.h>)
50	#include <cuda_profiler_api.h>
51	#define HAVE_CUDA_PROFILER_API 1
52	#endif
53	
54	// Helper functions and utilities to work with CUDA
55	#include <helper_cuda.h>
56	#include <helper_functions.h>
57	
58	/**
59	 * Matrix multiplication (CUDA Kernel) on the device: C = A * B
60	 * wA is A's width and wB is B's width
61	 */
62	template <int BLOCK_SIZE> __global__ void MatrixMulCUDA(float *C, float *A, float *B, int wA, int wB)
63	{
64	    // Block index
65	    int bx = blockIdx.x;
66	    int by = blockIdx.y;
67	
68	    // Thread index
69	    int tx = threadIdx.x;
70	    int ty = threadIdx.y;
71	
72	    // Index of the first sub-matrix of A processed by the block
73	    int aBegin = wA * BLOCK_SIZE * by;
74	
75	    // Index of the last sub-matrix of A processed by the block
76	    int aEnd = aBegin + wA - 1;
77	
78	    // Step size used to iterate through the sub-matrices of A
79	    int aStep = BLOCK_SIZE;
80	
81	    // Index of the first sub-matrix of B processed by the block
82	    int bBegin = BLOCK_SIZE * bx;
83	
84	    // Step size used to iterate through the sub-matrices of B
85	    int bStep = BLOCK_SIZE * wB;
86	
87	    // Csub is used to store the element of the block sub-matrix
88	    // that is computed by the thread
89	    float Csub = 0;
90	
91	    // Loop over all the sub-matrices of A and B
92	    // required to compute the block sub-matrix
93	    for (int a = aBegin, b = bBegin; a <= aEnd; a += aStep, b += bStep) {
94	        // Declaration of the shared memory array As used to
95	        // store the sub-matrix of A
96	        __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
97	
98	        // Declaration of the shared memory array Bs used to
99	        // store the sub-matrix of B
100	        __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];
101	
102	        // Load the matrices from device memory
103	        // to shared memory; each thread loads
104	        // one element of each matrix
105	        As[ty][tx] = A[a + wA * ty + tx];
106	        Bs[ty][tx] = B[b + wB * ty + tx];
107	
108	        // Synchronize to make sure the matrices are loaded
109	        __syncthreads();
110	
111	        // Multiply the two matrices together;
112	        // each thread computes one element
113	        // of the block sub-matrix
114	#pragma unroll
115	
116	        for (int k = 0; k < BLOCK_SIZE; ++k) {
117	            Csub += As[ty][k] * Bs[k][tx];
118	        }
119	
120	        // Synchronize to make sure that the preceding
121	        // computation is done before loading two new
122	        // sub-matrices of A and B in the next iteration
123	        __syncthreads();
124	    }
125	
126	    // Write the block sub-matrix to device memory;
127	    // each thread writes one element
128	    int c               = wB * BLOCK_SIZE * by + BLOCK_SIZE * bx;
129	    C[c + wB * ty + tx] = Csub;
130	}
131	
132	void ConstantInit(float *data, int size, float val)
133	{
134	    for (int i = 0; i < size; ++i) {
135	        data[i] = val;
136	    }
137	}
138	
139	/**
140	 * Run a simple test of matrix multiplication using CUDA
141	 */
142	int MatrixMultiply(int argc, char **argv, int block_size, const dim3 &dimsA, const dim3 &dimsB)
143	{
144	    // Allocate host memory for matrices A and B
145	    unsigned int size_A     = dimsA.x * dimsA.y;
146	    unsigned int mem_size_A = sizeof(float) * size_A;
147	    float       *h_A;
148	    checkCudaErrors(cudaMallocHost(&h_A, mem_size_A, 0));
149	    unsigned int size_B     = dimsB.x * dimsB.y;
150	    unsigned int mem_size_B = sizeof(float) * size_B;
151	    float       *h_B;
152	    checkCudaErrors(cudaMallocHost(&h_B, mem_size_B, 0));
153	    cudaStream_t stream;
154	
155	    // Initialize host memory
156	    const float valB = 0.01f;
157	    ConstantInit(h_A, size_A, 1.0f);
158	    ConstantInit(h_B, size_B, valB);
159	
160	    // Allocate device memory
161	    float *d_A, *d_B, *d_C;
162	
163	    // Allocate host matrix C
164	    dim3         dimsC(dimsB.x, dimsA.y, 1);
165	    unsigned int mem_size_C = dimsC.x * dimsC.y * sizeof(float);
166	    float       *h_C;
167	    checkCudaErrors(cudaMallocHost(&h_C, mem_size_C, 0));
168	
169	    if (h_C == NULL) {
170	        fprintf(stderr, "Failed to allocate host matrix C!\n");
171	        exit(EXIT_FAILURE);
172	    }
173	
174	    checkCudaErrors(cudaMalloc(reinterpret_cast<void **>(&d_A), mem_size_A));
175	    checkCudaErrors(cudaMalloc(reinterpret_cast<void **>(&d_B), mem_size_B));
176	    checkCudaErrors(cudaMalloc(reinterpret_cast<void **>(&d_C), mem_size_C));
177	    // Allocate CUDA events that we'll use for timing
178	    cudaEvent_t start, stop;
179	    checkCudaErrors(cudaEventCreate(&start));
180	    checkCudaErrors(cudaEventCreate(&stop));
181	
182	    checkCudaErrors(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
183	
184	    // copy host memory to device
185	    checkCudaErrors(cudaMemcpyAsync(d_A, h_A, mem_size_A, cudaMemcpyHostToDevice, stream));
186	    checkCudaErrors(cudaMemcpyAsync(d_B, h_B, mem_size_B, cudaMemcpyHostToDevice, stream));
187	
188	    // Setup execution parameters
189	    dim3 threads(block_size, block_size);
190	    dim3 grid(dimsB.x / threads.x, dimsA.y / threads.y);
191	
192	    // Create and start timer
193	    printf("Computing result using CUDA Kernel...\n");
194	
195	    // Performs warmup operation using matrixMul CUDA kernel
196	    if (block_size == 16) {
197	        MatrixMulCUDA<16><<<grid, threads, 0, stream>>>(d_C, d_A, d_B, dimsA.x, dimsB.x);
198	    }
199	    else {
200	        MatrixMulCUDA<32><<<grid, threads, 0, stream>>>(d_C, d_A, d_B, dimsA.x, dimsB.x);
201	    }
202	
203	    printf("done\n");
204	    checkCudaErrors(cudaStreamSynchronize(stream));
205	
206	    // Record the start event
207	    checkCudaErrors(cudaEventRecord(start, stream));
208	
209	    // Execute the kernel
210	    int nIter = 300;
211	
212	    for (int j = 0; j < nIter; j++) {
213	        if (block_size == 16) {
214	            MatrixMulCUDA<16><<<grid, threads, 0, stream>>>(d_C, d_A, d_B, dimsA.x, dimsB.x);
215	        }
216	        else {
217	            MatrixMulCUDA<32><<<grid, threads, 0, stream>>>(d_C, d_A, d_B, dimsA.x, dimsB.x);
218	        }
219	    }
220	
221	    // Record the stop event
222	    checkCudaErrors(cudaEventRecord(stop, stream));
223	
224	    // Wait for the stop event to complete
225	    checkCudaErrors(cudaEventSynchronize(stop));
226	
227	    float msecTotal = 0.0f;
228	    checkCudaErrors(cudaEventElapsedTime(&msecTotal, start, stop));
229	
230	    // Compute and print the performance
231	    float  msecPerMatrixMul = msecTotal / nIter;
232	    double flopsPerMatrixMul =
233	        2.0 * static_cast<double>(dimsA.x) * static_cast<double>(dimsA.y) * static_cast<double>(dimsB.x);
234	    double gigaFlops = (flopsPerMatrixMul * 1.0e-9f) / (msecPerMatrixMul / 1000.0f);
235	    printf("Performance= %.2f GFlop/s, Time= %.3f msec, Size= %.0f Ops,"
236	           " WorkgroupSize= %u threads/block\n",
237	           gigaFlops,
238	           msecPerMatrixMul,
239	           flopsPerMatrixMul,
240	           threads.x * threads.y);
241	
242	    // Copy result from device to host
243	    checkCudaErrors(cudaMemcpyAsync(h_C, d_C, mem_size_C, cudaMemcpyDeviceToHost, stream));
244	    checkCudaErrors(cudaStreamSynchronize(stream));
245	
246	    printf("Checking computed result for correctness: ");
247	    bool correct = true;
248	
249	    // test relative error by the formula
250	    //     |<x, y>_cpu - <x,y>_gpu|/<|x|, |y|>  < eps
251	    double eps = 1.e-6; // machine zero
252	
253	    for (int i = 0; i < static_cast<int>(dimsC.x * dimsC.y); i++) {
254	        double abs_err    = fabs(h_C[i] - (dimsA.x * valB));
255	        double dot_length = dimsA.x;
256	        double abs_val    = fabs(h_C[i]);
257	        double rel_err    = abs_err / abs_val / dot_length;
258	
259	        if (rel_err > eps) {
260	            printf("Error! Matrix[%05d]=%.8f, ref=%.8f error term is > %E\n", i, h_C[i], dimsA.x * valB, eps);
261	            correct = false;
262	        }
263	    }
264	
265	    printf("%s\n", correct ? "Result = PASS" : "Result = FAIL");
266	
267	    // Clean up memory
268	    checkCudaErrors(cudaFreeHost(h_A));
269	    checkCudaErrors(cudaFreeHost(h_B));
270	    checkCudaErrors(cudaFreeHost(h_C));
271	    checkCudaErrors(cudaFree(d_A));
272	    checkCudaErrors(cudaFree(d_B));
273	    checkCudaErrors(cudaFree(d_C));
274	    checkCudaErrors(cudaEventDestroy(start));
275	    checkCudaErrors(cudaEventDestroy(stop));
276	    printf("\nNOTE: The CUDA Samples are not meant for performance "
277	           "measurements. Results may vary when GPU Boost is enabled.\n");
278	
279	    if (correct) {
280	        return EXIT_SUCCESS;
281	    }
282	    else {
283	        return EXIT_FAILURE;
284	    }
285	}
286	
287	
288	/**
289	 * Program main
290	 */
291	int main(int argc, char **argv)
292	{
293	    printf("[Matrix Multiply Using CUDA] - Starting...\n");
294	
295	    if (checkCmdLineFlag(argc, (const char **)argv, "help") || checkCmdLineFlag(argc, (const char **)argv, "?")) {
296	        printf("Usage -device=n (n >= 0 for deviceID)\n");
297	        printf("      -wA=WidthA -hA=HeightA (Width x Height of Matrix A)\n");
298	        printf("      -wB=WidthB -hB=HeightB (Width x Height of Matrix B)\n");
299	        printf("  Note: Outer matrix dimensions of A & B matrices"
300	               " must be equal.\n");
301	
302	        exit(EXIT_SUCCESS);
303	    }
304	
305	    // This will pick the best possible CUDA capable device, otherwise
306	    // override the device ID based on input provided at the command line
307	    int dev = findCudaDevice(argc, (const char **)argv);
308	
309	    int block_size = 32;
310	
311	    dim3 dimsA(5 * 2 * block_size, 5 * 2 * block_size, 1);
312	    dim3 dimsB(5 * 4 * block_size, 5 * 2 * block_size, 1);
313	
314	    // width of Matrix A
315	    if (checkCmdLineFlag(argc, (const char **)argv, "wA")) {
316	        dimsA.x = getCmdLineArgumentInt(argc, (const char **)argv, "wA");
317	    }
318	
319	    // height of Matrix A
320	    if (checkCmdLineFlag(argc, (const char **)argv, "hA")) {
321	        dimsA.y = getCmdLineArgumentInt(argc, (const char **)argv, "hA");
322	    }
323	
324	    // width of Matrix B
325	    if (checkCmdLineFlag(argc, (const char **)argv, "wB")) {
326	        dimsB.x = getCmdLineArgumentInt(argc, (const char **)argv, "wB");
327	    }
328	
329	    // height of Matrix B
330	    if (checkCmdLineFlag(argc, (const char **)argv, "hB")) {
331	        dimsB.y = getCmdLineArgumentInt(argc, (const char **)argv, "hB");
332	    }
333	
334	    if (dimsA.x != dimsB.y) {
335	        printf("Error: outer matrix dimensions must be equal. (%d != %d)\n", dimsA.x, dimsB.y);
336	        exit(EXIT_FAILURE);
337	    }
338	
339	    printf("MatrixA(%d,%d), MatrixB(%d,%d)\n", dimsA.x, dimsA.y, dimsB.x, dimsB.y);
340	
341	#ifdef HAVE_CUDA_PROFILER_API
342	    checkCudaErrors(cudaProfilerStart());
343	#endif
344	    int matrix_result = MatrixMultiply(argc, argv, block_size, dimsA, dimsB);
345	#ifdef HAVE_CUDA_PROFILER_API
346	    checkCudaErrors(cudaProfilerStop());
347	#endif
348	
349	    exit(matrix_result);
350	}
